import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { cause12Schema, type Cause12 } from "./cause12.js";
import { workflowTypeSchema, type WorkflowType } from "./workflow-type.js";

export type StartChildWorkflowExecutionFailedEventAttributes = {
  workflowType: WorkflowType;
  /**
   * The cause of the failure. This information is generated by the system and can be useful for
   * diagnostic purposes. When cause is set to OPERATION_NOT_PERMITTED, the decision fails because
   * it lacks sufficient permissions. For details and example IAM policies, see Using IAM to Manage
   * Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
   */
  cause: Cause12;
  /** The workflowId of the child workflow execution. */
  workflowId: string;
  /**
   * When the cause is WORKFLOW_ALREADY_RUNNING, initiatedEventId is the ID of the
   * StartChildWorkflowExecutionInitiated event that corresponds to the StartChildWorkflowExecution
   * Decision to start the workflow execution. You can use this information to diagnose problems by
   * tracing back the chain of events leading up to this event. When the cause isn't
   * WORKFLOW_ALREADY_RUNNING, initiatedEventId is set to 0 because the
   * StartChildWorkflowExecutionInitiated event doesn't exist.
   */
  initiatedEventId: number;
  /**
   * The ID of the DecisionTaskCompleted event corresponding to the decision task that resulted in
   * the StartChildWorkflowExecution Decision to request this child workflow execution. This
   * information can be useful for diagnosing problems by tracing back the chain of events.
   */
  decisionTaskCompletedEventId: number;
  /**
   * The data attached to the event that the decider can use in subsequent workflow tasks. This data
   * isn't sent to the child workflow execution.
   */
  control?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const startChildWorkflowExecutionFailedEventAttributesSchema: Schema<StartChildWorkflowExecutionFailedEventAttributes> =
  s.object<StartChildWorkflowExecutionFailedEventAttributes>(
    {
      workflowType: workflowTypeSchema,
      cause: cause12Schema,
      workflowId: s.string(),
      initiatedEventId: s.int(),
      decisionTaskCompletedEventId: s.int(),
      control: s.optional(s.string()),
    },
    { additionalProperties: s.json() },
  );
